package main

import "fmt"

// Package-level variables
var appName = "BelajarGo"
var version = "1.0"

func main() {
	// var dengan tipe eksplisit
	var nama string = "Gopher"
	var umur int = 5

	// Short declaration
	kota := "Jakarta"
	tinggi := 1.80

	// Multiple assignment
	x, y := 10, 20
	x, y = y, x // swap!

	fmt.Printf("App: %s v%s\n", appName, version)
	fmt.Printf("Nama: %s, Umur: %d tahun\n", nama, umur)
	fmt.Printf("Kota: %s, Tinggi: %.2f\n", kota, tinggi)
	fmt.Printf("x=%d, y=%d (setelah swap)\n", x, y)
}
